package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.base.*;
import com.punjab.oms.ar.domain.dto.finance.*;import com.punjab.oms.ar.enums.*;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import java.math.BigDecimal;import java.time.LocalDate;import java.nio.file.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-invoice-eligibility：开票独立额度及原组调整口径验证。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.invoice-eligibility.real",matches="true") @EnabledIfSystemProperty(named="ar.invoice-eligibility.real.commit",matches="true")
class InvoiceEligibilityRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired com.punjab.oms.ar.config.InvoiceProperties policy;@Autowired CustomerBalanceService balances;@Autowired InvoiceEligibilityService eligibility;@Autowired ReceiptService receipts;@Autowired OffsetService offsets;@Autowired ReceivableService receivables;@Autowired SettlementService settlements;@Autowired JdbcTemplate jdbc;
 private String key(){return UUID.randomUUID().toString();} private BigDecimal n(String v){return new BigDecimal(v);}
 private void actor(){CurrentUser.set(new CurrentUser.Identity("offset-test",Set.of(1L),Set.of("ar:create","ar:read","ar:settle","ar:reverse","ar:receipt:create","ar:balance:transfer")));}
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");
  for(String name:List.of("V001__ar_core.sql","V002__ar_audit.sql","V003__ar_receipt.sql","V004__ar_settlement.sql","V005__ar_adjustment_link.sql","V006__ar_customer_balance.sql","V009__ar_exchange_basis.sql")){var file=Path.of("../scratch/dbddl/"+name);if(Files.exists(file))for(String sql:Files.readString(file).split(";"))if(!sql.isBlank())jdbc.execute(sql);}actor();}
 @AfterEach void clear(){policy.setExchangeDifferenceEnabled(false);CurrentUser.clear();}
 private long line(AmountType type,String amount,Long group,Long original){
  long doc=receivables.create(new ReceivableCreateRequest(key(),1L,1L,"CNY","TAX_ADJUSTMENT",LocalDate.now(),null,"test",List.of(new ReceivableCreateRequest.Line("A",group,type,n(amount),type==AmountType.OUTPUT_TAX?n("0.13"):null,type==AmountType.OUTPUT_TAX?n("100"):null,null,original))));
  return jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);
 }
 private long group(long line){return jdbc.queryForObject("SELECT group_id FROM oms_ar_line WHERE id=?",Long.class,line);}
 private BigDecimal open(long line){return jdbc.queryForObject("SELECT open_amount FROM oms_ar_line WHERE id=?",BigDecimal.class,line);}
 private OffsetPreviewRequest request(long negative,String amount,List<Long> groups,boolean more){return new OffsetPreviewRequest(1L,negative,n(amount),groups,more,AllocationStrategy.GROUP_TAX_FIRST);}

 private com.punjab.oms.ar.domain.vo.finance.InvoiceEligibilityResponse quota(Long... groups){return eligibility.query(new com.punjab.oms.ar.domain.query.finance.InvoiceEligibilityQuery(1L,1L,"CNY",List.of(groups)));}
 private BigDecimal blue(long group,String type){return quota(group).buckets().stream().filter(b->b.amountType().equals(type)).map(b->b.blueAvailableAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);}
 @Test @DisplayName("未收与全额收款核销后的开票额度一致")void settlementIndependent(){long price=line(AmountType.PRINCIPAL,"100",null,null),tax=line(AmountType.OUTPUT_TAX,"13",group(price),null);assertThat(quota(group(price))).isNotNull();assertThat(blue(group(price),"PRINCIPAL")).isEqualByComparingTo("100");long receipt=receipts.create(new ReceiptCreateRequest(key(),1L,1L,"CNY",n("113"),LocalDate.now(),"TEST",key(),"quota"));var request=new SettlementPreviewRequest(1L,receipt,n("113"),List.of(group(price)),AllocationStrategy.GROUP_TAX_FIRST);settlements.confirm(new SettlementConfirmRequest(key(),request,settlements.preview(request).fingerprint(),"paid"));assertThat(open(price)).isEqualByComparingTo("0");assertThat(blue(group(price),"PRINCIPAL")).isEqualByComparingTo("100");assertThat(blue(group(price),"OUTPUT_TAX")).isEqualByComparingTo("13");}
 @Test @DisplayName("关联负数计入原组而非自身新组，抵销不重复扣额度")void related(){long tax=line(AmountType.OUTPUT_TAX,"13",null,null),credit=line(AmountType.OUTPUT_TAX,"-4",null,tax);var view=quota(group(tax));assertThat(view).isNotNull();assertThat(blue(group(tax),"OUTPUT_TAX")).isEqualByComparingTo("9");assertThat(view.lines()).extracting(x->x.id()).contains(credit);assertThat(quota(group(credit)).buckets()).isEmpty();var request=request(credit,"4",List.of(),false);offsets.confirm(new OffsetConfirmRequest(key(),request,offsets.preview(request).fingerprint(),"adjust"));assertThat(blue(group(tax),"OUTPUT_TAX")).isEqualByComparingTo("9");}
 @Test @DisplayName("独立负数只影响自己的开票组")void standalone(){long tax=line(AmountType.OUTPUT_TAX,"13",null,null),credit=line(AmountType.OUTPUT_TAX,"-4",null,null);assertThat(quota(group(tax))).isNotNull();var request=request(credit,"4",List.of(group(tax)),false);offsets.confirm(new OffsetConfirmRequest(key(),request,offsets.preview(request).fingerprint(),"independent"));assertThat(blue(group(tax),"OUTPUT_TAX")).isEqualByComparingTo("13");assertThat(quota(group(credit)).buckets().getFirst().remainingNetAmount()).isEqualByComparingTo("-4");}
 @Test @DisplayName("跨主体或跨客户选择业务组被拒绝")void scope(){long price=line(AmountType.PRINCIPAL,"100",null,null);assertThatThrownBy(()->eligibility.query(new com.punjab.oms.ar.domain.query.finance.InvoiceEligibilityQuery(1L,2L,"CNY",List.of(group(price))))).isInstanceOf(ServiceException.class);assertThatThrownBy(()->eligibility.query(new com.punjab.oms.ar.domain.query.finance.InvoiceEligibilityQuery(2L,1L,"CNY",List.of(group(price))))).isInstanceOf(RuntimeException.class);}

 @Test @DisplayName("不同税率额度独立，旧税率冲回后只剩新税率额度")void changedRate(){
  long oldTax=line(AmountType.OUTPUT_TAX,"13",null,null);line(AmountType.OUTPUT_TAX,"-13",null,oldTax);
  receivables.create(new ReceivableCreateRequest(key(),1L,1L,"CNY","TAX_ADJUSTMENT",LocalDate.now(),null,"new rate",List.of(new ReceivableCreateRequest.Line("A",group(oldTax),AmountType.OUTPUT_TAX,n("9"),n("0.09"),n("100"),null))));
  var view=quota(group(oldTax));assertThat(view.buckets()).hasSize(2);assertThat(view.buckets().stream().filter(b->b.taxRate().compareTo(n("0.13"))==0).findFirst().orElseThrow().blueAvailableAmount()).isEqualByComparingTo("0");assertThat(view.buckets().stream().filter(b->b.taxRate().compareTo(n("0.09"))==0).findFirst().orElseThrow().blueAvailableAmount()).isEqualByComparingTo("9");assertThat(jdbc.queryForObject("SELECT tax_rate FROM oms_ar_line WHERE id=?",BigDecimal.class,oldTax)).isEqualByComparingTo("0.13");
 }
 @Test @DisplayName("续抵其他组不将原组开票调整转移到资金抵销目标")void crossGroup(){long original=line(AmountType.OUTPUT_TAX,"3",null,null),other=line(AmountType.OUTPUT_TAX,"26",null,null),credit=line(AmountType.OUTPUT_TAX,"-10",null,original);var request=request(credit,"10",List.of(group(other)),true);offsets.confirm(new OffsetConfirmRequest(key(),request,offsets.preview(request).fingerprint(),"cross group"));assertThat(open(other)).isEqualByComparingTo("19");assertThat(blue(group(other),"OUTPUT_TAX")).isEqualByComparingTo("26");assertThat(quota(group(original)).buckets().getFirst().remainingNetAmount()).isEqualByComparingTo("-7");}
 @Test @DisplayName("负数转余额不撤销原组的开票调整")void transferred(){long original=line(AmountType.OUTPUT_TAX,"13",null,null),credit=line(AmountType.OUTPUT_TAX,"-4",null,original);balances.transfer(new BalanceTransferRequest(key(),1L,credit,n("4"),0L,"credit account"));assertThat(open(credit)).isEqualByComparingTo("0");assertThat(blue(group(original),"OUTPUT_TAX")).isEqualByComparingTo("9");}
 @Test @DisplayName("已开票净额独立扣减，共享额度不能按单行剩余相加")void invoiced(){long price=line(AmountType.PRINCIPAL,"100",null,null),credit=line(AmountType.PRINCIPAL,"-20",null,price);
  // 模拟已落账开票聚合，登记与流水事务由后续开票服务单独验证。
  jdbc.update("UPDATE oms_ar_line SET invoiced_amount=60,version=version+1 WHERE id=?",price);assertThat(blue(group(price),"PRINCIPAL")).isEqualByComparingTo("20");
  jdbc.update("UPDATE oms_ar_line SET invoiced_amount=-10,version=version+1 WHERE id=?",credit);var bucket=quota(group(price)).buckets().getFirst();assertThat(bucket.invoicedNetAmount()).isEqualByComparingTo("50");assertThat(bucket.blueAvailableAmount()).isEqualByComparingTo("30");
  jdbc.update("UPDATE oms_ar_line SET invoiced_amount=100,version=version+1 WHERE id=?",price);jdbc.update("UPDATE oms_ar_line SET invoiced_amount=-20,version=version+1 WHERE id=?",credit);assertThat(blue(group(price),"PRINCIPAL")).isEqualByComparingTo("0");
 }
 @Test @DisplayName("汇率差异默认禁开，显式开启且有依据才计入额度")void exchangePolicy(){var basis=new ReceivableCreateRequest.ExchangeBasis("USD",n("100"),n("7.1"),n("7.3"),ExchangeRateDirection.SETTLEMENT_PER_ORIGINAL);long doc=receivables.create(new ReceivableCreateRequest(key(),1L,1L,"CNY","EXCHANGE_DIFFERENCE",LocalDate.now(),null,"fx",List.of(new ReceivableCreateRequest.Line("A",null,AmountType.PRINCIPAL,n("20"),null,null,null,null,basis))));long line=jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);var blocked=quota(group(line));assertThat(blocked.buckets()).isEmpty();assertThat(blocked.lines().getFirst().blockedReason()).isEqualTo("EXCHANGE_DIFFERENCE_DISABLED");policy.setExchangeDifferenceEnabled(true);var enabled=quota(group(line));assertThat(enabled.fingerprint()).isNotEqualTo(blocked.fingerprint());assertThat(enabled.buckets().getFirst().blueAvailableAmount()).isEqualByComparingTo("20");
  long legacy=line(AmountType.PRINCIPAL,"20",null,null);jdbc.update("UPDATE oms_ar_document SET business_type='EXCHANGE_DIFFERENCE' WHERE id=?",jdbc.queryForObject("SELECT document_id FROM oms_ar_line WHERE id=?",Long.class,legacy));assertThat(quota(group(legacy)).lines().getFirst().blockedReason()).isEqualTo("EXCHANGE_BASIS_MISSING");assertThat(quota(group(legacy)).buckets()).isEmpty();
 }
 @Test @DisplayName("作废明细不贡献额度，重复组选取拒绝")void inactive(){long tax=line(AmountType.OUTPUT_TAX,"13",null,null),credit=line(AmountType.OUTPUT_TAX,"-4",null,tax);jdbc.update("UPDATE oms_ar_line SET status='VOID',open_amount=0 WHERE id=?",credit);assertThat(blue(group(tax),"OUTPUT_TAX")).isEqualByComparingTo("13");assertThatThrownBy(()->quota(group(tax),group(tax))).isInstanceOf(ServiceException.class);}

 @Test @DisplayName("指定原行的负数调整必须保留原税率")void mismatchedOriginalRate(){long original=line(AmountType.OUTPUT_TAX,"13",null,null);var request=new ReceivableCreateRequest(key(),1L,1L,"CNY","TAX_ADJUSTMENT",LocalDate.now(),null,"wrong rate",List.of(new ReceivableCreateRequest.Line("A",null,AmountType.OUTPUT_TAX,n("-4"),n("0.09"),n("100"),null,original)));assertThatThrownBy(()->receivables.create(request)).isInstanceOf(ServiceException.class);}
 @Test @DisplayName("历史原行税率不一致时拒绝给出虚高额度")void legacyMismatchedRate(){long original=line(AmountType.OUTPUT_TAX,"13",null,null),credit=line(AmountType.OUTPUT_TAX,"-4",null,original);jdbc.update("UPDATE oms_ar_line SET tax_rate=0.09 WHERE id=?",credit);assertThatThrownBy(()->quota(group(original))).isInstanceOf(ServiceException.class);}
}
